<script lang="ts" setup>
import type {MaterialOption} from '../../material/api';import type {LocationItem,WarehouseItem} from '../../warehouse/api';import type {CustomerOption,PromiseAssessment,PromiseDashboard,SalesOrder,Shipment} from '../api';import {onMounted,ref} from 'vue';import {Page} from '@vben/common-ui';import {message,Modal} from 'antdv-next';import {$t} from '#/locales';import {getMaterialOptionsApi} from '../../material/api';import {getWarehouseListApi,getWarehouseTreeApi} from '../../warehouse/api';import {assessOrderPromiseApi,cancelSalesOrderApi,confirmSalesOrderApi,createSalesOrderApi,createShipmentApi,getOrderPromiseApi,getPromiseDashboardApi,getSalesCustomerOptionsApi,getSalesOrderApi,getSalesOrdersApi,getShipmentsApi} from '../api';
const tab=ref('orders'),loading=ref(false),saving=ref(false),orderVisible=ref(false),shipmentVisible=ref(false),orders=ref<SalesOrder[]>([]),shipments=ref<Shipment[]>([]),selected=ref<SalesOrder>(),customers=ref<CustomerOption[]>([]),materials=ref<MaterialOption[]>([]),warehouses=ref<WarehouseItem[]>([]),locations=ref<LocationItem[]>([]),form=ref<Record<string,any>>({}),promiseDashboard=ref<PromiseDashboard>(),promises=ref<PromiseAssessment[]>([]);
function flatten(nodes:any[]):LocationItem[]{return nodes.flatMap(n=>[...(n.node_type==='AREA'?[]:[{id:n.id,warehouse_id:0,area_id:0,location_code:n.code,location_name:n.name,location_type:n.node_type,location_level:1,status:n.status,storage_enabled:n.storage_enabled,mixed_material_allowed:false,mixed_lot_allowed:false,sort_no:0} as LocationItem]),...flatten(n.children??[])]);}async function options(){[customers.value,materials.value,warehouses.value]=await Promise.all([getSalesCustomerOptionsApi(),getMaterialOptionsApi({sellable:true}),getWarehouseListApi()]);const trees=await Promise.all(warehouses.value.map(w=>getWarehouseTreeApi(w.id)));locations.value=trees.flatMap((t,i)=>flatten(t.children).map(x=>({...x,warehouse_id:warehouses.value[i]?.id??0})));}async function load(){loading.value=true;try{[orders.value,shipments.value,promiseDashboard.value]=await Promise.all([getSalesOrdersApi(),getShipmentsApi(),getPromiseDashboardApi()]);if(selected.value){selected.value=await getSalesOrderApi(selected.value.id);promises.value=await getOrderPromiseApi(selected.value.id);}}finally{loading.value=false;}}async function select(row:SalesOrder){selected.value=await getSalesOrderApi(row.id);promises.value=await getOrderPromiseApi(row.id);}async function assessPromise(){if(!selected.value)return;promises.value=await assessOrderPromiseApi(selected.value.id);promiseDashboard.value=await getPromiseDashboardApi();message.success('ATP/CTP 评估已刷新');}function locs(id?:number){return locations.value.filter(x=>x.warehouse_id===id&&x.storage_enabled).map(x=>({label:`${x.location_code} · ${x.location_name}`,value:x.id}));}
function openOrder(){form.value={customer_id:undefined,material_id:undefined,ordered_quantity:1,unit_price:undefined,currency:'CNY'};orderVisible.value=true;}function openShipment(){const line=selected.value?.lines.find(x=>Number(x.shipped_quantity)<Number(x.ordered_quantity));if(!selected.value||!line)return;form.value={sales_order_id:selected.value.id,sales_order_line_id:line.id,quantity:Number(line.ordered_quantity)-Number(line.shipped_quantity),warehouse_id:undefined,location_id:undefined,lot_id:undefined};shipmentVisible.value=true;}async function saveOrder(){saving.value=true;try{const{material_id,ordered_quantity,unit_price,...head}=form.value;selected.value=await createSalesOrderApi({...head,lines:[{material_id,ordered_quantity,unit_price}]});orderVisible.value=false;message.success($t('sales.created'));await load();}finally{saving.value=false;}}async function saveShipment(){saving.value=true;try{const{sales_order_id,sales_order_line_id,...line}=form.value;await createShipmentApi({sales_order_id,lines:[{sales_order_line_id,...line}]});shipmentVisible.value=false;tab.value='shipments';message.success($t('sales.shippedMessage'));await load();}finally{saving.value=false;}}async function confirm(){if(!selected.value)return;selected.value=await confirmSalesOrderApi(selected.value.id);message.success($t('sales.confirmed'));await load();}function cancel(){if(!selected.value)return;Modal.confirm({title:$t('sales.cancel'),async onOk(){if(!selected.value)return;selected.value=await cancelSalesOrderApi(selected.value.id);message.success($t('sales.cancelled'));await load();}});}onMounted(async()=>{await options();await load();});
void assessPromise;
</script>
<template><Page :title="$t('sales.menu')"><div class="flex h-full min-h-0 gap-4"><a-card class="min-w-0 flex-1" :bordered="false"><div class="mb-3 flex gap-2"><a-button type="primary" @click="openOrder">{{ $t('sales.create') }}</a-button><a-button @click="openShipment">{{ $t('sales.ship') }}</a-button><a-button @click="load">{{ $t('sales.refresh') }}</a-button></div><a-tabs v-model:active-key="tab"><a-tab-pane key="orders" :tab="$t('sales.orders')"><a-table :loading="loading" :data-source="orders" row-key="id" @row="(r:SalesOrder)=>({onClick:()=>select(r)})"><a-table-column :title="$t('sales.orderNo')" data-index="sales_order_no"/><a-table-column :title="$t('sales.customer')" data-index="customer_name_snapshot"/><a-table-column :title="$t('sales.status')" data-index="status"/></a-table></a-tab-pane><a-tab-pane key="shipments" :tab="$t('sales.shipments')"><a-table :loading="loading" :data-source="shipments" row-key="id"><a-table-column :title="$t('sales.shipmentNo')" data-index="shipment_no"/><a-table-column :title="$t('sales.customer')" data-index="customer_name_snapshot"/><a-table-column :title="$t('sales.status')" data-index="status"/></a-table></a-tab-pane></a-tabs></a-card><a-card class="w-[440px] shrink-0" :bordered="false" :title="selected?.sales_order_no??$t('sales.orders')"><a-empty v-if="!selected"/><template v-else><a-descriptions :column="1"><a-descriptions-item :label="$t('sales.customer')">{{selected.customer_name_snapshot}}</a-descriptions-item><a-descriptions-item :label="$t('sales.status')">{{selected.status}}</a-descriptions-item></a-descriptions><div class="my-3 flex gap-2"><a-button v-if="selected.status==='DRAFT'" type="primary" @click="confirm">{{ $t('sales.confirm') }}</a-button><a-button v-if="['DRAFT','CONFIRMED'].includes(selected.status)" danger @click="cancel">{{ $t('sales.cancel') }}</a-button><a-button v-if="['CONFIRMED','PARTIALLY_SHIPPED'].includes(selected.status)" @click="openShipment">{{ $t('sales.ship') }}</a-button></div><a-table :data-source="selected.lines" row-key="id" size="small" :pagination="false"><a-table-column :title="$t('sales.material')" data-index="material_name_snapshot"/><a-table-column :title="$t('sales.ordered')" data-index="ordered_quantity"/><a-table-column :title="$t('sales.shipped')" data-index="shipped_quantity"/></a-table></template></a-card></div>
<a-modal v-model:open="orderVisible" :title="$t('sales.create')" :confirm-loading="saving" @ok="saveOrder"><a-form layout="vertical" :model="form"><a-form-item :label="$t('sales.customer')"><a-select v-model:value="form.customer_id" show-search :options="customers.map(x=>({label:`${x.code} · ${x.name}`,value:x.id}))"/></a-form-item><a-form-item :label="$t('sales.material')"><a-select v-model:value="form.material_id" show-search :options="materials.map(x=>({label:`${x.code} · ${x.name}`,value:x.id}))"/></a-form-item><a-form-item :label="$t('sales.ordered')"><a-input-number v-model:value="form.ordered_quantity" class="w-full" :min="0.000001"/></a-form-item><a-form-item :label="$t('sales.price')"><a-input-number v-model:value="form.unit_price" class="w-full" :min="0"/></a-form-item></a-form></a-modal>
<a-modal v-model:open="shipmentVisible" :title="$t('sales.ship')" :confirm-loading="saving" @ok="saveShipment"><a-form layout="vertical" :model="form"><a-form-item :label="$t('sales.quantity')"><a-input-number v-model:value="form.quantity" class="w-full" :min="0.000001"/></a-form-item><a-form-item :label="$t('sales.warehouse')"><a-select v-model:value="form.warehouse_id" :options="warehouses.map(x=>({label:`${x.warehouse_code} · ${x.warehouse_name}`,value:x.id}))" @change="form.location_id=undefined"/></a-form-item><a-form-item :label="$t('sales.location')"><a-select v-model:value="form.location_id" :options="locs(form.warehouse_id)"/></a-form-item><a-form-item :label="$t('sales.lot')"><a-input-number v-model:value="form.lot_id" class="w-full" :min="1"/></a-form-item></a-form></a-modal></Page></template>
void assessPromise;
